import pptx

pptx_path = "/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/a3fbeb63-0e8c-4a11-bff6-0e3b484c3e9c.pptx"

def extract_all_text(pptx_path):
    prs = pptx.Presentation(pptx_path)
    results = []
    for idx, slide in enumerate(prs.slides, start=1):
        texts = []
        for shape in slide.shapes:
            if hasattr(shape, "text") and shape.text:
                texts.append(shape.text)
        # notes (if present)
        if getattr(slide, "has_notes_slide", False):
            try:
                notes = slide.notes_slide.notes_text_frame.text
                if notes:
                    texts.append(notes)
            except Exception:
                pass
        results.append({"slide_number": idx, "text": " ".join(t.strip() for t in texts if t.strip())})
    return results

slides = extract_all_text(pptx_path)
for s in slides:
    print(f"Slide {s['slide_number']}: {s['text']}\n")

